        const size_t aligned_size = align_size(size + 1);
        if (UNLIKELY(!aligned_size))
            return false;
        char *buffer = realloc(s->value.buffer, aligned_size);
        if (UNLIKELY(!buffer))
            return false;
        s->value.buffer = buffer;
